const kill = () => { try { chrome.kill('SIGKILL'); } catch {} rmSync(profile, { recursive: true, force: true }); };
setTimeout(() => { console.error('timeout'); kill(); process.exit(2); }, 90000);
const port = await new Promise((resolve) => { let buf = ''; chrome.stderr.on('data', (d) => { buf += d; const m = /DevTools listening on ws:\/\/127\.0\.0\.1:(\d+)/.exec(buf); if (m) resolve(m[1]); }); });
const targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
