const scrollTo = flags.find((f) => f.startsWith('scroll='));
if (scrollTo) { await send('Runtime.evaluate', { expression: `document.querySelector('${scrollTo.slice(7)}').scrollIntoView({block:'start'})` }); await new Promise((r) => setTimeout(r, +(flags.find((f) => f.startsWith('after='))?.slice(6) ?? 6000))); }
