const info = flags.includes('nojs') ? { result: { value: 'scripts off' } } : await send('Runtime.evaluate', { returnByValue: true, expression: `JSON.stringify({scrollWidth: document.documentElement.scrollWidth, innerWidth, height: document.documentElement.scrollHeight, copyStatus: document.querySelector('.copy-status')?.textContent, copyHidden: document.querySelector('.copy')?.hidden, shownLines: document.querySelectorAll('.term-lines p.shown').length, playing: document.querySelector('.term-lines')?.classList.contains('playing'), fonts: [...document.fonts].filter(f=>f.status==='loaded').map(f=>f.family).filter((v,i,a)=>a.indexOf(v)===i)})` });
const full = flags.includes('full');
const metrics = await send('Page.getLayoutMetrics');
const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: full, ...(full ? { clip: { x: 0, y: 0, width: +width, height: Math.min(metrics.cssContentSize.height, 9000), scale: 1 } } : {}) });
writeFileSync(out, Buffer.from(shot.data, 'base64'));
console.log(out, info.result?.value, logs.length ? logs.join(' | ') : 'no console errors');
